INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 3, 'theory', 'Quiz: ES5, ES6, Babel and tooling');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 3, 0, 'Why did ten years pass between ES3 and ES5?', '["Nobody wanted to develop the language", "The language was legally blocked", "A committee split over the ambitious ES4 and the need to support old browsers", "Everyone was waiting for Node.js"]', 2, 'ES4 was cancelled in 2008, the modest ideas (ES3.1) became ES5; new syntax could not be used while IE6–IE8 were widespread.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 3, 1, 'What did the fifth edition, ES5 (2009), bring?', '["Strict mode, the JSON object, array methods forEach/map/filter/reduce", "Classes and modules", "async/await", "Arrow functions"]', 0, 'Classes, modules and arrows appeared only in ES2015, and async/await in ES2017.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 3, 2, 'What does Babel do?', '["Compresses images", "Parses code into a tree and transforms new syntax into old syntax that the target browsers understand", "Runs JavaScript on the server", "Replaces npm"]', 1, 'Plugins and presets describe the transformations; missing built-in objects are filled by core-js polyfills, and the target browsers are set by browserslist.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 3, 3, 'What features did the Sass, Less and Stylus preprocessors add to CSS?', '["Asynchronous requests", "Data types", "Classes", "Variables, nested rules, mixins and file imports"]', 3, 'Today some of these features (variables, nesting) have appeared in CSS itself.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 3, 4, 'What happened to the left-pad package in March 2016?', '["Its author removed the 11-line package from npm, and builds around the world broke", "It was included in the language standard", "It became part of webpack", "It was replaced by Babel"]', 0, 'The incident showed how fragile supply chains are: huge trees of tiny dependencies rely on each other.');
